\iff  \left(\frac{1}{2}\overrightarrow{BC} + \frac{1}{2}\overrightarrow{BA}\right) \cdot \left(\frac{1}{2} \overrightarrow{BA} - \overrightarrow{BC}\right)  &= 0 
\iff \frac{1}{4} \overrightarrow{BC} \cdot \overrightarrow{BA} + \frac{1}{4}\overrightarrow{BA} \cdot \overrightarrow{BA} - \frac{1}{2} \overrightarrow{BC} \cdot \overrightarrow{BC} - \frac{1}{2} \overrightarrow{BA} \cdot \overrightarrow{BC} &= 0 
\iff - \overrightarrow{BC} \cdot \overrightarrow{BA} + c^2 - 2a^2 &= 0 
\iff -a c \cos \angle ABC + c^2 - 2a^2 &= 0,
\end{align*}
and by the cosine rule,  $ac\cos \angle ABC = \frac{a^2 + c^2 - b^2}{2}$ , thus  $BD \perp CD$  iff
\begin{align*}
    -\frac{a^2 + c^2 - b^2}{2} + c^2 - 2a^2 &= 0 
